<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch,nextTick} from 'vue'
const props=defineProps<{employeeId?:number;compact?:boolean;hideEmpty?:boolean}>()
const emit=defineEmits<{(event:'changed'):void}>()
const data=ref<any>({accounts:[],entries:[],canEdit:false}),search=ref(''),error=ref(''),busy=ref(false),historyId=ref<number|null>(null),refund=ref<any>(null),review=ref(false)
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const money=(value:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(value)||0)
const date=(value:any)=>{const d=String(value||'').slice(0,10);return d?new Date(d+'T00:00:00Z').toLocaleDateString('en-PH',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'}):'-'}
const filteredAccounts=computed(()=>data.value.accounts.filter((a:any)=>[a.EmployeeName,a.EmployeeNumber,a.AgencyName,a.DeductionName,a.ClassificationName].join(' ').toLowerCase().includes(search.value.toLowerCase())))
const totals=computed(()=>filteredAccounts.value.reduce((t:any,a:any)=>({collected:t.collected+Number(a.TotalCollected),refunded:t.refunded+Number(a.TotalRefunded),balance:t.balance+Number(a.Balance)}),{collected:0,refunded:0,balance:0}))
const selected=computed(()=>data.value.accounts.find((a:any)=>Number(a.AccountID)===historyId.value))
const entries=computed(()=>data.value.entries.filter((entry:any)=>Number(entry.AccountID)===historyId.value))
async function load(historyEmployeeId?:number){try{data.value=await $fetch('/api/deductions-loans/cash-bonds',{query:{...(props.employeeId?{employeeId:props.employeeId}:{}),...(historyEmployeeId?{historyEmployeeId}:{})}})}catch(e:any){error.value=e.data?.statusMessage||'Unable to load refundable deductions.'}}
async function history(a:any){historyId.value=Number(a.AccountID);error.value='';await load(Number(a.EmployeeID))}
function newRequestKey(){return typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),value=>value.toString(16).padStart(2,'0')).join('')}
function startRefund(entry?:any){error.value='';review.value=false;refund.value={Action:entry?'reverse-refund':'refund',AccountID:selected.value.AccountID,Revision:selected.value.Revision,SourceRefundID:entry?.EntryID,Amount:entry?Number(entry.Amount):'',TransactionDate:today(),Reference:'',Reason:'',RequestKey:newRequestKey(),confirmed:false}}
async function saveRefund(){busy.value=true;error.value='';try{await $fetch('/api/deductions-loans/cash-bonds/refund',{method:'POST',body:refund.value});refund.value=null;review.value=false;await load(Number(selected.value.EmployeeID));emit('changed')}catch(e:any){error.value=e.data?.statusMessage||'Unable to record this transaction.';review.value=false}finally{busy.value=false}}
let oldOverflow='',focusBefore:HTMLElement|null=null
const anyModal=computed(()=>historyId.value!==null||!!refund.value)
watch(anyModal,async opened=>{if(opened){oldOverflow=document.body.style.overflow;focusBefore=document.activeElement as HTMLElement;document.body.style.overflow='hidden';await nextTick();document.querySelector<HTMLElement>('.bond-backdrop:last-of-type button')?.focus()}else{document.body.style.overflow=oldOverflow;focusBefore?.focus()}})
function onKey(event:KeyboardEvent){if(busy.value||!anyModal.value)return;if(event.key==='Escape'){event.preventDefault();if(refund.value)refund.value=null;else historyId.value=null;review.value=false}if(event.key==='Tab'){const dialogs=document.querySelectorAll<HTMLElement>('.bond-modal'),dialog=dialogs[dialogs.length-1],nodes=dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!nodes?.length)return;const first=nodes[0]!,last=nodes[nodes.length-1]!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}}
watch(()=>props.employeeId,()=>{historyId.value=null;refund.value=null;load()})
onMounted(()=>{load();document.addEventListener('keydown',onKey)})
onBeforeUnmount(()=>{if(anyModal.value)document.body.style.overflow=oldOverflow;document.removeEventListener('keydown',onKey)})
</script>
<template>
 <section v-if="!hideEmpty || data.accounts.length || error" class="bonds-page"><header v-if="compact"><h4>Refundable funds</h4><p class="funds-caption">Lifetime collections, refunds and the current amount available to return, across all cutoffs.</p></header>
  <p v-if="!compact" class="notice">Standard amounts follow the employee's agency and position. Payroll can enter a different total for one employee and cutoff; the next cutoff returns to the standard. Each refundable item has its own balance.</p>
  <label v-if="!compact" class="search">Search<input v-model="search" type="search" placeholder="Employee, agency or deduction item"></label>
  <p v-if="error&&!historyId" role="alert" class="error">{{error}}</p>
   <div v-if="!compact" class="totals"><article><span>Total collected</span><strong>{{money(totals.collected)}}</strong></article><article><span>Total refunded</span><strong>{{money(totals.refunded)}}</strong></article><article><span>Available balance</span><strong>{{money(totals.balance)}}</strong></article></div>
   <div class="table-wrap"><table><thead><tr><th v-if="!employeeId">Employee</th><th>Agency / item</th><th>Collected</th><th>Refunded</th><th>Available</th><th></th></tr></thead><tbody><tr v-for="a in filteredAccounts" :key="a.AccountID"><td v-if="!employeeId"><strong>{{a.EmployeeName}}</strong><small>{{a.EmployeeNumber||'EMP-'+String(a.EmployeeID).padStart(4,'0')}}</small></td><td>{{a.AgencyName}}<small>{{a.ClassificationName}} / {{a.DeductionName}}</small></td><td>{{money(a.TotalCollected)}}</td><td>{{money(a.TotalRefunded)}}</td><td><strong>{{money(a.Balance)}}</strong></td><td><button @click="history(a)">View history</button></td></tr><tr v-if="!filteredAccounts.length"><td :colspan="employeeId?5:6" class="empty">No refundable deduction collections yet. Balances appear after payroll is finalized.</td></tr></tbody></table></div>
  <Teleport to="body">
   <div v-if="historyId&&selected" class="bond-backdrop"><section class="bond-modal history-modal" role="dialog" aria-modal="true" aria-labelledby="history-title"><header><div><p class="eyebrow">REFUNDABLE DEDUCTION ACCOUNT</p><h2 id="history-title">{{selected.EmployeeName}}</h2><p>{{selected.AgencyName}} / {{selected.DeductionName}}</p></div><button aria-label="Close history" :disabled="busy" @click="historyId=null;refund=null">&times;</button></header><div class="modal-body"><div class="totals"><article><span>Collected</span><strong>{{money(selected.TotalCollected)}}</strong></article><article><span>Refunded</span><strong>{{money(selected.TotalRefunded)}}</strong></article><article><span>Available</span><strong>{{money(selected.Balance)}}</strong></article></div><button v-if="data.canEdit" class="primary" :disabled="Number(selected.Balance)<=0" @click="startRefund()">Record refund</button><p class="notice">Collections are added only from finalized payroll. A refund records money already returned to the employee.</p><div v-for="entry in entries" :key="entry.EntryID" class="ledger-entry"><div><strong>{{entry.EntryType==='RefundReversal'?'Refund reversal':entry.EntryType}}</strong><span>{{money(entry.Amount)}}</span><small>{{date(entry.TransactionDate)}} / {{entry.Reference}} / {{entry.Status}}{{entry.IsReversed?' / Reversed':''}}</small><small>{{entry.Reason}} / {{entry.ActorName}}</small></div><button v-if="data.canEdit&&entry.EntryType==='Refund'&&!entry.IsReversed&&entry.Status==='Posted'" @click="startRefund(entry)">Reverse recorded refund</button></div><p v-if="error&&!refund" role="alert" class="error">{{error}}</p></div><footer><button @click="historyId=null">Close</button></footer></section></div>
   <div v-if="refund" class="bond-backdrop refund-layer"><form class="bond-modal" role="dialog" aria-modal="true" aria-labelledby="refund-title" @submit.prevent="review?saveRefund():review=true"><header><div><p class="eyebrow">REFUND RECORD</p><h2 id="refund-title">{{review?'Confirm transaction':refund.Action==='refund'?'Record refundable deduction refund':'Reverse a recorded refund'}}</h2></div><button type="button" :disabled="busy" aria-label="Close refund" @click="refund=null">&times;</button></header><div class="modal-body"><p>{{selected.EmployeeName}} / {{selected.AgencyName}} / {{selected.DeductionName}}</p><template v-if="!review"><div class="fields"><label>Amount<input v-model="refund.Amount" type="number" step="0.01" min="0.01" :max="refund.Action==='refund'?selected.Balance:undefined" :readonly="refund.Action!=='refund'" required></label><label>Transaction date<input v-model="refund.TransactionDate" type="date" :max="today()" required></label></div><label>Payment / correction reference<input v-model.trim="refund.Reference" minlength="5" maxlength="150" required></label><label>Reason<textarea v-model.trim="refund.Reason" minlength="5" maxlength="500" required/></label><label class="check"><input v-model="refund.confirmed" type="checkbox" required><span>{{refund.Action==='refund'?'I confirm this refund has been paid to the employee.':'I confirm this refund record must be reversed.'}}</span></label></template><template v-else><p><strong>{{money(refund.Amount)}}</strong> / {{date(refund.TransactionDate)}}</p><p>{{refund.Reference}}</p><p>{{refund.Reason}}</p><p class="notice">{{refund.Action==='refund'?'This will reduce the available refundable deduction balance.':'This will restore the amount to the available refundable deduction balance.'}}</p></template><p v-if="error" role="alert" class="error">{{error}}</p></div><footer><button type="button" :disabled="busy" @click="review?review=false:refund=null">{{review?'Back':'Cancel'}}</button><button class="primary" :disabled="busy">{{busy?'Saving...':review?'Confirm record':'Review transaction'}}</button></footer></form></div>
  </Teleport>
 </section>
</template>
<style scoped>
.funds-caption{color:#7185a2;font-size:.78rem;line-height:1.5;margin:5px 0 16px}h4{font-size:.9rem;margin:0}

.bonds-page{box-sizing:border-box;padding:0;color:#173457;max-width:1500px;margin:auto;font-family:Inter,system-ui,sans-serif}.page-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.eyebrow{color:#2563eb;font-size:.72rem;font-weight:800;letter-spacing:.08em;margin:0 0 7px}h1{margin:0;font-size:1.9rem}h2{margin:0;font-size:1.4rem}.page-heading p:not(.eyebrow){color:#72859f;font-size:.87rem;line-height:1.6}button{font:inherit;cursor:pointer;border:1px solid #cbd8ed;border-radius:8px;padding:9px 13px;background:#fff;color:#28548f;font-size:.8rem;font-weight:700;min-height:38px}button:disabled{opacity:.5;cursor:default}.primary{color:#fff;background:#2563eb;border-color:#2563eb}.notice{background:#edf4ff;border:1px solid #d6e5fb;padding:13px 16px;border-radius:10px;color:#496c98;font-size:.8rem;line-height:1.6}.tabs{display:flex;gap:20px;border-bottom:1px solid #dce5f3;margin:25px 0}.tabs button{border:0;border-radius:0;background:none;padding:12px 0;color:#72859f}.tabs button.active{border-bottom:3px solid #2563eb;color:#2563eb}.search{max-width:500px;margin-bottom:20px}label{display:grid;gap:7px;font-size:.8rem;font-weight:650;color:#506888}input,select,textarea{box-sizing:border-box;min-width:0;width:100%;min-height:42px;padding:9px 11px;border:1px solid #cbd8ed;border-radius:8px;font:inherit;background:#fff;color:#19395f}input:focus,select:focus,textarea:focus{outline:3px solid #dfeaff;border-color:#7e9fd9}.totals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0}.totals article{padding:18px;background:#fff;border:1px solid #dce5f3;border-radius:11px;min-width:0}.totals span{font-size:.75rem;color:#72859f}.totals strong{display:block;margin-top:8px;font-size:1.35rem;font-variant-numeric:tabular-nums}.table-wrap{overflow:auto;border:1px solid #dce5f3;border-radius:12px;background:#fff}table{width:100%;border-collapse:collapse;min-width:740px;font-size:.81rem}th{background:#f4f7fc;text-align:left;font-size:.7rem;color:#68809f;text-transform:uppercase}td,th{padding:15px;border-bottom:1px solid #e5ecf6}td small{display:block;color:#72859f;margin-top:5px;font-size:.73rem}.empty{padding:35px;text-align:center;color:#72859f}.error{background:#fff1f2;color:#b42318;padding:12px;border-radius:8px;font-size:.8rem}.bond-backdrop{position:fixed;inset:0;z-index:610;background:#10243f80;display:grid;place-items:center;padding:16px;font-family:Inter,system-ui,sans-serif;color:#18365c}.bond-modal{box-sizing:border-box;display:flex;flex-direction:column;max-height:92dvh;width:min(100%,650px);background:#fff;border:1px solid #dce5f3;border-radius:16px;box-shadow:0 20px 65px #0c203640;min-height:0}.bond-modal header{display:flex;justify-content:space-between;align-items:flex-start;padding:23px;border-bottom:1px solid #e5ecf6;gap:16px}.bond-modal header>button{border:0;background:none;font-size:1.4rem;padding:0;width:30px;min-height:30px}.bond-modal header p:not(.eyebrow){font-size:.8rem;color:#72859f;margin-bottom:0}.modal-body{padding:22px;overflow:auto;min-height:0;display:grid;align-content:start;gap:16px}.modal-body p{margin:0;font-size:.83rem;line-height:1.6}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.bond-modal footer{display:flex;justify-content:flex-end;gap:10px;padding:15px 22px;border-top:1px solid #e5ecf6}.history-modal{width:min(100%,850px)}.history-modal .totals{margin:0}.ledger-entry{padding:15px;border:1px solid #dce5f3;border-radius:9px;display:flex;justify-content:space-between;align-items:center;gap:12px}.ledger-entry strong{font-size:.85rem}.ledger-entry span{margin-left:16px;font-weight:700}.ledger-entry small{display:block;margin-top:5px;color:#72859f;font-size:.73rem;line-height:1.5}.refund-layer{z-index:620}.check{display:flex;align-items:flex-start;gap:10px;line-height:1.6}.check input{width:16px;min-height:16px;flex:none;margin-top:2px}@media(max-width:650px){.bonds-page{padding:0}.page-heading{flex-direction:column}h1{font-size:1.6rem}.totals{gap:8px}.totals article{padding:12px}.totals strong{font-size:1.05rem}.bond-backdrop{padding:10px}.bond-modal{max-height:calc(100dvh - 20px)}.bond-modal header{padding:17px}.modal-body{padding:16px}.fields{grid-template-columns:1fr}.ledger-entry{align-items:stretch;flex-direction:column}.bond-modal footer button{flex:1}.tabs{gap:18px}.tabs button{font-size:.75rem}}
</style>
